    RelationDSU(int n,int mod):mod(mod),p(n),sz(n,1),rel(n){iota(p.begin(),p.end(),0);}
    int norm(int x)const{x%=mod;return x<0?x+mod:x;}
    int find(int x){if(p[x]==x)return x;int old=p[x];p[x]=find(old);rel[x]=norm(rel[x]+rel[old]);return p[x];}
    bool add(int x,int y,int d){
        d=norm(d);int rx=find(x),ry=find(y);
        if(rx==ry)return norm(rel[x]-rel[y])==d;
        int delta=norm(d-rel[x]+rel[y]);
        if(sz[rx]<=sz[ry]){p[rx]=ry;rel[rx]=delta;sz[ry]+=sz[rx];}
        else {p[ry]=rx;rel[ry]=norm(-delta);sz[rx]+=sz[ry];}
        return true;
    }
};

struct LCA{
