            }else low[u]=min(low[u],dfn[v]);
        }
        if(parentEdge==-1&&children>1)cut[u]=true;
    };
    for(int u=0;u<n;++u)if(!dfn[u])dfs(u,-1);return {cut,bridges};
}

struct Activity{int u,v;long long w;};
tuple<bool,long long,vector<int>> criticalPath(int n,const vector<Activity>& edges){
    vector<vector<int>>g(n);vector<int>deg(n),order;vector<long long>ve(n);
    for(int i=0;i<(int)edges.size();++i){g[edges[i].u].push_back(i);++deg[edges[i].v];}
    queue<int>q;for(int i=0;i<n;++i)if(!deg[i])q.push(i);
    while(!q.empty()){int u=q.front();q.pop();order.push_back(u);
        for(int id:g[u]){auto e=edges[id];ve[e.v]=max(ve[e.v],ve[u]+e.w);if(!--deg[e.v])q.push(e.v);}}
    if((int)order.size()!=n)return {false,0,{}};
    long long total=n?*max_element(ve.begin(),ve.end()):0;vector<long long>vl(n,total);
    for(int i=n-1;i>=0;--i){int u=order[i];for(int id:g[u]){auto e=edges[id];vl[u]=min(vl[u],vl[e.v]-e.w);}}
    vector<int>key;for(int i=0;i<(int)edges.size();++i){auto e=edges[i];if(ve[e.u]==vl[e.v]-e.w)key.push_back(i);}
