long long inversionCount(vector<int>& a) {
    vector<int> b(a.size());
    function<long long(int,int)> solve=[&](int l,int r)->long long {
        if(r-l<=1) return 0;
        int m=l+(r-l)/2;
        long long ans=solve(l,m)+solve(m,r);
        int i=l,j=m,k=l;
        while(i<m && j<r) {
            if(a[i]<=a[j]) b[k++]=a[i++];
            else {ans+=m-i; b[k++]=a[j++];}
        }
        while(i<m) b[k++]=a[i++];
        while(j<r) b[k++]=a[j++];
        copy(b.begin()+l,b.begin()+r,a.begin()+l);
        return ans;
    };
    return solve(0,(int)a.size());
}

