        while(r-l>1){int pivot=a[l+rng()%(r-l)],lt=l,i=l,gt=r;
            while(i<gt){if(a[i]<pivot)swap(a[lt++],a[i++]);else if(a[i]>pivot)swap(a[i],a[--gt]);else ++i;}
            if(lt-l<r-gt){sortRange(l,lt);l=gt;}else {sortRange(gt,r);r=lt;}
