vector<vector<int>> replacementSelection(const vector<int>& a,int m) {
    priority_queue<int,vector<int>,greater<int>> active,frozen;
    size_t pos=0;
    while(pos<a.size() && active.size()<(size_t)m) active.push(a[pos++]);
    vector<vector<int>> runs;
    while(!active.empty()) {
        vector<int> run;
        while(!active.empty()) {
            int x=active.top(); active.pop(); run.push_back(x);
            if(pos<a.size()) {
                int y=a[pos++];
                if(y>=x) active.push(y); else frozen.push(y);
            }
        }
        runs.push_back(move(run)); active.swap(frozen);
    }
    return runs;
}

vector<long long> mergeRuns(const vector<vector<long long>>& runs) {
    using Item=tuple<long long,int,int>;
    priority_queue<Item,vector<Item>,greater<Item>> q;
    for(int i=0;i<(int)runs.size();++i)
        if(!runs[i].empty()) q.push({runs[i][0],i,0});
    vector<long long> out;
    while(!q.empty()) {
        auto [x,i,j]=q.top();q.pop();out.push_back(x);
        if(j+1<(int)runs[i].size()) q.push({runs[i][j+1],i,j+1});
    }
    return out;
}

pair<long long,int> kHuffman(vector<long long> w,int k) {
    using Item=pair<long long,int>;
    priority_queue<Item,vector<Item>,greater<Item>> q;
    for(auto x:w) q.push({x,0});
    int extra=(k-1-((int)w.size()-1)%(k-1))%(k-1);
    while(extra--) q.push({0,0});
    long long total=0;
    while(q.size()>1) {
        long long sum=0; int h=0;
        for(int i=0;i<k;++i) {
            auto [v,d]=q.top();q.pop(); sum+=v; h=max(h,d);
        }
        total+=sum; q.push({sum,h+1});
    }
    return {total,q.top().second};
}

