}

struct LoserTree {
    int k; vector<int> loser; vector<long long> key; vector<bool> alive;
    LoserTree(vector<long long> a, vector<bool> valid):k((int)a.size()),loser(k,k),key(a),alive(valid){
        for(int i=k-1;i>=0;--i) adjust(i);
    }
    bool lessPlayer(int a,int b) const {
        if(a==k || b==k) return a==k && b!=k;
        if(alive[a]!=alive[b]) return alive[a];
        if(!alive[a]) return a<b;
        return key[a]!=key[b]?key[a]<key[b]:a<b;
    }
    void adjust(int s){
        for(int p=(s+k)/2;p>0;p/=2)
            if(lessPlayer(loser[p],s)) swap(s,loser[p]);
        if(k) loser[0]=s;
    }
    int winner() const {return k && alive[loser[0]]?loser[0]:-1;}
    void replaceWinner(long long value,bool valid){
        int s=winner();if(s<0)return;key[s]=value;alive[s]=valid;adjust(s);
    }
};

