    explicit LinearSet(int m):key(m),state(m){assert(m>0);}
    int start(long long x) const {long long m=key.size();return int((x%m+m)%m);}
    bool contains(long long x) const {
        int m=key.size(),h=start(x);
        for(int d=0;d<m;++d){int i=(h+d)%m;if(state[i]==0)return false;if(state[i]==1&&key[i]==x)return true;}
