        int m=key.size(),h=start(x),slot=-1;
        for(int d=0;d<m;++d){int i=(h+d)%m;
            if(state[i]==1&&key[i]==x)return true;
            if(state[i]!=1&&slot<0)slot=i;
            if(state[i]==0)break;
        }
        if(slot<0)return false;key[slot]=x;state[slot]=1;return true;
    }
    bool erase(long long x){
        int m=key.size(),h=start(x);
        for(int d=0;d<m;++d){int i=(h+d)%m;if(state[i]==0)return false;
