long long optimalBST(const vector<long long>& p,const vector<long long>& q) {
    int n=p.size();
    vector<long long> sp(n+1),sq(n+2);
    for(int i=0;i<n;++i) sp[i+1]=sp[i]+p[i];
    for(int i=0;i<=n;++i) sq[i+1]=sq[i]+q[i];
    vector<vector<long long>> dp(n+1,vector<long long>(n+1));
    vector<vector<int>> opt(n+1,vector<int>(n+1));
    for(int i=0;i<=n;++i) opt[i][i]=i;
    for(int len=1;len<=n;++len) for(int l=0;l+len<=n;++l) {
        int r=l+len; // keys [l,r), gaps [l,r]
        long long w=sp[r]-sp[l]+sq[r+1]-sq[l];
        dp[l][r]=LLONG_MAX;
        int low=opt[l][r-1],high=min(r-1,opt[l+1][r]);
        for(int root=low;root<=high;++root) {
            long long cost=dp[l][root]+dp[root+1][r]+w;
            if(cost<dp[l][r]) { dp[l][r]=cost;opt[l][r]=root; }
        }
    }
    return dp[0][n];
}

struct Fenwick {
