            if(y<=n && bit[y]<k) { x=y;k-=bit[y]; }
        }
        return x+1;
    }
};

struct SplayCore {
    struct Node { int ch[2]{},fa=0,cnt=1,size=1; };
    vector<Node> a{Node{}}; int root=0;
    int size(int x) const { return x?a[x].size:0; }
    void pull(int x) { if(x)a[x].size=size(a[x].ch[0])+size(a[x].ch[1])+a[x].cnt; }
    void rotate(int x) {
        int y=a[x].fa,z=a[y].fa,d=(a[y].ch[1]==x),b=a[x].ch[d^1];
        if(z)a[z].ch[a[z].ch[1]==y]=x; else root=x;
        a[x].fa=z; a[x].ch[d^1]=y; a[y].fa=x;
        a[y].ch[d]=b; if(b)a[b].fa=y;
        pull(y);pull(x);
    }
    void splay(int x) {
        while(a[x].fa) {
            int y=a[x].fa,z=a[y].fa;
            if(z) rotate((a[y].ch[1]==x)==(a[z].ch[1]==y)?y:x);
            rotate(x);
        }
        root=x;
    }
};

struct AVL {
    struct Node { int key,l=0,r=0,h=1,cnt=1; };
    vector<Node> a{{0}}; int root=0;
    int height(int u) const { return u?a[u].h:0; }
    void pull(int u) { a[u].h=1+max(height(a[u].l),height(a[u].r)); }
    int rotateRight(int u) {
        int v=a[u].l; a[u].l=a[v].r; a[v].r=u;pull(u);pull(v);return v;
    }
    int rotateLeft(int u) {
        int v=a[u].r; a[u].r=a[v].l; a[v].l=u;pull(u);pull(v);return v;
    }
    int insert(int u,int key) {
        if(!u) { a.push_back(Node{key});return (int)a.size()-1; }
        if(key==a[u].key) { ++a[u].cnt;return u; }
        if(key<a[u].key) { int v=insert(a[u].l,key);a[u].l=v; }
        else { int v=insert(a[u].r,key);a[u].r=v; }
        pull(u); int b=height(a[u].l)-height(a[u].r);
        if(b>1) {
            if(key>a[a[u].l].key) a[u].l=rotateLeft(a[u].l);
            return rotateRight(u);
        }
        if(b< -1) {
            if(key<a[a[u].r].key) a[u].r=rotateRight(a[u].r);
            return rotateLeft(u);
        }
        return u;
    }
    void insert(int key) { root=insert(root,key); }
};

vector<int> suffixArray(const string& s) {
    int n=s.size(); vector<int> sa(n),rank(n),tmp(n),buf(n);
    iota(sa.begin(),sa.end(),0);
    for(int i=0;i<n;++i) rank[i]=(unsigned char)s[i]+1;
    auto get=[&](int i){return i<n?rank[i]:0;};
    for(int k=1;k<n;k*=2) {
        int m=max(n,256)+1; vector<int> count(m);
        auto counting=[&](int shift) {
            fill(count.begin(),count.end(),0);
            for(int i:sa) ++count[get(i+shift)];
            for(int i=1;i<m;++i) count[i]+=count[i-1];
            for(int j=n-1;j>=0;--j) {
                int i=sa[j];buf[--count[get(i+shift)]]=i;
            }
            sa.swap(buf);
        };
        counting(k);counting(0);
        int classes=1;tmp[sa[0]]=classes;
        for(int i=1;i<n;++i) {
            int x=sa[i-1],y=sa[i];
            if(rank[x]!=rank[y] || get(x+k)!=get(y+k)) ++classes;
            tmp[y]=classes;
        }
        rank.swap(tmp);if(classes==n)break;
    }
    return sa;
}

struct BinaryTrie {
