        nodes.push_back({!list,list?'\0':text[pos],{}});++pos;
        if(!list)return u;
        skip();while(text[pos]!=')'){
            int v=parse();nodes[u].child.push_back(v);skip();
            if(text[pos]==','){++pos;skip();}
        }
        ++pos;return u;
    }
    int length(int u)const{return nodes[u].atom?0:int(nodes[u].child.size());}
    int depth(int u)const{
        if(nodes[u].atom)return 0;int best=0;
        for(int v:nodes[u].child)best=max(best,depth(v));return best+1;
    }
};

vector<bool> markReachable(const vector<vector<int>>& refs,const vector<int>& roots){
    vector<bool> live(refs.size());vector<int> st;
    for(int r:roots)if(!live[r]){live[r]=true;st.push_back(r);}
    while(!st.empty()){
        int u=st.back();st.pop_back();
        for(int v:refs[u])if(!live[v]){live[v]=true;st.push_back(v);}
    }
    return live;
}

struct SequenceSplay {
    struct Node{int ch[2]={0,0},fa=0,size=1,value=0;bool rev=false;};
    vector<Node> a;int root=0,n;
    explicit SequenceSplay(int count):a(count+3),n(count){a[0].size=0;root=build(0,n+1,0);}
    void pull(int u){a[u].size=a[a[u].ch[0]].size+a[a[u].ch[1]].size+1;}
    void flip(int u){if(u){swap(a[u].ch[0],a[u].ch[1]);a[u].rev=!a[u].rev;}}
    void push(int u){if(a[u].rev){flip(a[u].ch[0]);flip(a[u].ch[1]);a[u].rev=false;}}
    int build(int l,int r,int fa){
        if(l>r)return 0;int m=(l+r)/2,u=m+1;a[u].value=m;a[u].fa=fa;
        a[u].ch[0]=build(l,m-1,u);a[u].ch[1]=build(m+1,r,u);pull(u);return u;
    }
    void rotate(int x){
        int y=a[x].fa,z=a[y].fa,d=(a[y].ch[1]==x),b=a[x].ch[d^1];
        if(z)a[z].ch[a[z].ch[1]==y]=x;else root=x;a[x].fa=z;
        a[y].ch[d]=b;if(b)a[b].fa=y;
        a[x].ch[d^1]=y;a[y].fa=x;pull(y);pull(x);
    }
    void splay(int x,int goal=0){
        vector<int> path;for(int u=x;u!=goal;u=a[u].fa)path.push_back(u);
        for(auto it=path.rbegin();it!=path.rend();++it)push(*it);
        while(a[x].fa!=goal){int y=a[x].fa,z=a[y].fa;
            if(z!=goal)rotate((a[y].ch[1]==x)==(a[z].ch[1]==y)?y:x);
            rotate(x);
        }
    }
    int kth(int k){
        int u=root;while(u){push(u);int left=a[a[u].ch[0]].size;
            if(k==left+1)return u;if(k<=left)u=a[u].ch[0];else{k-=left+1;u=a[u].ch[1];}}
        return 0;
    }
    void reverseRange(int l,int r){
        assert(1<=l&&l<=r&&r<=n);int x=kth(l);splay(x);int y=kth(r+2);splay(y,x);
        flip(a[y].ch[0]);pull(y);pull(x);
    }
    vector<int> values(){
        vector<int> ans,st;int u=root;
        while(u||!st.empty()){
            while(u){push(u);st.push_back(u);u=a[u].ch[0];}
            u=st.back();st.pop_back();if(a[u].value>=1&&a[u].value<=n)ans.push_back(a[u].value);
            u=a[u].ch[1];
        }
        return ans;
    }
};

struct CSR {
    int rows,cols;vector<int> rowPtr,column;vector<long long> value;
    CSR(int r,int c,vector<tuple<int,int,long long>> entries):rows(r),cols(c),rowPtr(r+1){
        sort(entries.begin(),entries.end());
        for(int i=0;i<(int)entries.size();){
            auto [rr,cc,v]=entries[i++];
            while(i<(int)entries.size()&&get<0>(entries[i])==rr&&get<1>(entries[i])==cc)v+=get<2>(entries[i++]);
            if(v){++rowPtr[rr+1];column.push_back(cc);value.push_back(v);}
        }
        for(int i=1;i<=rows;++i)rowPtr[i]+=rowPtr[i-1];
    }
    vector<long long> multiply(const vector<long long>& x)const{
        assert((int)x.size()==cols);vector<long long> y(rows);
        for(int i=0;i<rows;++i)for(int p=rowPtr[i];p<rowPtr[i+1];++p)y[i]+=value[p]*x[column[p]];
        return y;
    }
};
